alter table public.twiga_platform_secret_refs drop constraint if exists twiga_platform_secret_refs_provider_check;
alter table public.twiga_platform_secret_refs add constraint twiga_platform_secret_refs_provider_check check (provider = any (array['xai','google_oauth_client_id','google_oauth_client_secret','google_token_encryption_key','retell_platform_api_key','palpluss_platform_api_key','sautikit_platform_api_key','twiga_scheduled_calls_cron_secret']::text[]));
insert into public.twiga_platform_secret_refs(provider,vault_secret_id,secret_last4,updated_by) select 'twiga_scheduled_calls_cron_secret',id,right(decrypted_secret,4),null from vault.decrypted_secrets where name='twiga_scheduled_calls_cron_secret' on conflict(provider) do update set vault_secret_id=excluded.vault_secret_id,secret_last4=excluded.secret_last4,updated_at=now();
